// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import { HashRouter, Route, Switch } from 'react-router-dom';
import {
  HeaderContainer,
  Header,
  HeaderMenuButton,
  HeaderName,
  SideNav,
  SideNavItems,
  SideNavLink,
} from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

const App = () => (
  <HashRouter>
    {/* The HeaderContainer manages isSideNavExpanded and onClickSideNavExpand for us */}
    <HeaderContainer
      render={({ isSideNavExpanded, onClickSideNavExpand }) => (
        <>
          <Header aria-label="Carbon React Shell">
            {/* Hamburger / Close button */}
            <HeaderMenuButton
              aria-label="Open menu"
              isActive={isSideNavExpanded}
              onClick={onClickSideNavExpand}
            />
            <HeaderName href="#" prefix="Company">
              Full product name
            </HeaderName>
            {/* SideNav is not persistent so on small viewports it overlays the page */}
            <SideNav
              expanded={isSideNavExpanded}
              isPersistent={false}
              aria-label="Side navigation"
            >
              <SideNavItems>
                <SideNavLink element={Link} to="/link1">
                  Link 1
                </SideNavLink>
                <SideNavLink element={Link} to="/link2">
                  Link 2
                </SideNavLink>
              </SideNavItems>
            </SideNav>
          </Header>
        </>
      )}
    />

    <main id="main-content">
      <Switch>
        <Route path="/link1">
          <div style={{ padding: '1rem' }}>Content for Link 1</div>
        </Route>
        <Route path="/link2">
          <div style={{ padding: '1rem' }}>Content for Link 2</div>
        </Route>
        <Route>
          <div style={{ padding: '1rem' }}>Home Content</div>
        </Route>
      </Switch>
    </main>
  </HashRouter>
);

ReactDOM.render(<App />, document.getElementById('root'));

